const errorData = $input.first().json;
const execution = errorData.execution || {};
const error = execution.error || {};
const execUrl = execution.url || '';
const lastNode = execution.lastNodeExecuted || 'unknown';
const errorDetail = (error.description || error.message || 'unknown').substring(0, 300);
const now = new Date().toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' });
const discordBody = {
  username: 'n8n',
  embeds: [{
    title: '\u26a0\ufe0f n8n \u30a8\u30e9\u30fc',
    color: 15158332,
    fields: [
      { name: '\u30ce\u30fc\u30c9', value: lastNode, inline: true },
      { name: '\u6642\u523b', value: now, inline: true },
      { name: '\u30a8\u30e9\u30fc', value: errorDetail },
      { name: '\u5b9f\u884c\u30ed\u30b0', value: execUrl || 'N/A' }
    ]
  }]
};
return [{ json: { discordBody: JSON.stringify(discordBody) } }];
